// The web's view of rumu's wire types.
//
// Types with a Rust counterpart are generated by ts-rs into ./generated
// (run `cargo test` after changing one); this module re-exports them so
// components keep importing from `~/lib/types`. Only the ad-hoc WebSocket
// protocol, push payloads (built with `json!` in the kernel), UI-only types
// and the tag/version constants are written by hand.

import type { Branch } from './generated/Branch'
import type { BranchId } from './generated/BranchId'
import type { CodeCall } from './generated/CodeCall'
import type { Content } from './generated/Content'
import type { Decision } from './generated/Decision'
import type { Node } from './generated/Node'
import type { PathState } from './generated/PathState'
import type { SessionInfo } from './generated/SessionInfo'
import type { Tagged } from './generated/Tagged'
import type { TaskId } from './generated/TaskId'
import type { TaskInfo } from './generated/TaskInfo'
import type { ReasoningBlock } from './generated/ReasoningBlock'
import type { TaskKind } from './generated/TaskKind'

export type { Tagged } from './generated/Tagged'
export type { Content } from './generated/Content'
export type { ToolCall } from './generated/ToolCall'
export type { Usage } from './generated/Usage'
export type { ReasoningBlock } from './generated/ReasoningBlock'

/** The visible thinking text of a reply's reasoning blocks. */
export function reasoningText(blocks: ReasoningBlock[] | null | undefined): string {
  return (blocks ?? []).map((b) => (b.type === 'thinking' ? b.text : '')).join('')
}
export type { NodeBody } from './generated/NodeBody'
export type { Node } from './generated/Node'
export type { NodeId } from './generated/NodeId'
export type { SessionId } from './generated/SessionId'
export type { BranchId } from './generated/BranchId'
export type { TaskId } from './generated/TaskId'
export type { BranchKind } from './generated/BranchKind'
export type { Inherit } from './generated/Inherit'
export type { InheritContext } from './generated/InheritContext'
export type { BranchStatus } from './generated/BranchStatus'
export type { Branch } from './generated/Branch'
export type { SessionInfo } from './generated/SessionInfo'
export type { TaskStatus } from './generated/TaskStatus'
export type { TaskKind } from './generated/TaskKind'
export type { TaskInfo } from './generated/TaskInfo'
export type { TaskDone } from './generated/TaskDone'
export type { Workspace } from './generated/Workspace'
export type { WorkspaceUse as WorkspaceUseMarkerData } from './generated/WorkspaceUse'
export type { PathState } from './generated/PathState'
export type { Decision } from './generated/Decision'
export type { CodeCall } from './generated/CodeCall'
export type { CatalogEntry } from './generated/CatalogEntry'
export type { FoldedCatalogDir } from './generated/FoldedCatalogDir'
export type { CatalogScope } from './generated/CatalogScope'
export type { CatalogNote } from './generated/CatalogNote'
export type { CardImport } from './generated/CardImport'
export type { CardUpdate } from './generated/CardUpdate'
export type { CardUse } from './generated/CardUse'
export type { CardInfo as Card } from './generated/CardInfo'
export type { AgentsNote } from './generated/AgentsNote'

/** Milliseconds since the Unix epoch (rumu-core's `Timestamp` alias). */
export type Timestamp = number

/** A plugin-authored tail append: a note's content (an empty-text note is a
 * marker). The kernel fills the node's `source` with the plugin's name. */
export type Effect = Content

/** The tag/version the catalog payload uses. */
export const CATALOG_TAG = 'memory.catalog'
export const CATALOG_VERSION = 2

export const TASK_TAG = 'kernel.task'
export const TASK_VERSION = 1

/**
 * The built-in workspace holding rumu's own data (`@rumu:/cards`,
 * `@rumu:/sessions`). Mirrors `RUMU_WORKSPACE` in rumu-core; the leading `@`
 * means no user preset can collide with it.
 */
export const INTERNAL_WORKSPACE = '@rumu'

// ---- WebSocket protocol ----

export interface WsRequest {
  jsonrpc: '2.0'
  id: number
  method: string
  params: Record<string, unknown>
}

export type WsMessage =
  | { jsonrpc: '2.0'; id: number; result: unknown }
  | { jsonrpc: '2.0'; id: number; error: { code: number; message: string } }
  | { jsonrpc: '2.0'; method: string; params: Record<string, unknown> }

export interface SessionTreeResult {
  session: SessionInfo
  nodes: Node[]
  branches: Branch[]
  /** Internal `code` calls (trace only; never nodes). */
  code_calls?: CodeCall[]
}

export interface BranchPathResult {
  nodes: Node[]
  state: PathState
}

// ---- Push payloads ----

export interface NodeAppendedPush {
  branch: BranchId
  node: Node
}

export interface LlmDeltaPush {
  branch: BranchId
  text?: string
  reasoning?: string
}

export interface BranchUpdatedPush {
  branch: Branch
}

export interface SessionUpdatedPush {
  session: SessionInfo
}

export interface HookFiredPush {
  branch: BranchId
  event: string
  plugin: string
  hook_id: string
  effects: Effect[]
  decision: Decision
  /** Set when the event came from an internal `code` call. */
  parent_call?: string
}

/** `tool.progress` push: a running tool's incremental update. */
export interface ToolProgressPush {
  branch: BranchId
  call_id: string
  /** Append-only text chunk. */
  append?: string
  /** Whole structured payload (latest wins). */
  data?: Tagged
}

/** `task.started` / `task.done` push: a task snapshot. */
export interface TaskInfoPush {
  task: TaskInfo
}

/** `task.progress` push: a running task's incremental output. */
export interface TaskProgressPush {
  id: TaskId
  branch: BranchId
  /** Append-only text chunk. */
  append?: string
  /** Latest structured payload (whole value, latest wins). */
  data?: Tagged
  /** Sent once when a background agent's child branch is created. */
  kind?: TaskKind
}

/** `code.call` push: one internal call finished (output is display-sized). */
export type CodeCallPush = CodeCall

export interface TurnPush {
  branch: BranchId
  /** Why the turn started. */
  reason?: 'prompt' | 'regenerate' | 'wake'
  /** Posting plugins, for wake turns. */
  sources?: string[]
}

/** A user prompt accepted while the branch was busy; it lands on the path at
 * the next safe point and arrives as a normal `node.appended` user node. */
export interface PromptQueuedPush {
  branch: BranchId
  text: string
}

export interface TurnErrorPush {
  branch: BranchId
  message: string
}

/** Non-fatal server warning (e.g. a failed post delivery). */
export interface WarningPush {
  message: string
}

export type ToastKind = 'error' | 'info'
